<?php
namespace App\Livewire\Documents;
use App\Domain\Documents\Services\AuthorizedDocumentQuery;use App\Domain\Documents\Services\DocumentAccessRecorder;use App\Models\Document;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')]
class DocumentViewer extends Component{public Document $document;public function mount(Document $document,AuthorizedDocumentQuery $authorized,DocumentAccessRecorder $access):void{abort_unless(app(\App\Domain\Authorization\Services\PermissionResolver::class)->allows(auth()->user(),'documents.preview'),403);abort_unless($authorized->for(auth()->user())->whereKey($document->id)->exists(),403);$this->document=$document->load(['currentVersion.files','documentType','district','revenueCircle','mouza','village','barcode']);$access->record($document,'PREVIEW','SUCCESS',$this->previewFile());}public function previewFile(){return $this->document->currentVersion?->files->firstWhere('file_role','PREVIEW')??$this->document->currentVersion?->files->firstWhere('file_role','OPTIMIZED')??$this->document->currentVersion?->files->firstWhere('file_role','MASTER');}public function render(){return view('livewire.documents.document-viewer',['file'=>$this->previewFile()]);}}
